import * as T from 'three';
const SPECIES={rabbit:{name:'Conejo',hp:8,speed:4.6,meat:1,hide:0,mode:'flee',color:0xb4a18a,size:.6},deer:{name:'Ciervo',hp:20,speed:5.1,meat:3,hide:1,mode:'flee',color:0xa47b51,size:1},boar:{name:'Jabalí',hp:30,speed:3.9,meat:3,hide:1,mode:'territorial',color:0x736457,size:.9},wolf:{name:'Lobo',hp:26,speed:4.5,meat:2,hide:2,mode:'hostile',color:0x87938c,size:.85}};
export function createWildlife({world,visual,character,greyMan,state,now,active,unlocked,reward,hurt,spend,save,toast,lineFree}){
 const animals=[],defs=[['rabbit',-52,79],['rabbit',-68,70],['deer',-37,65],['deer',-81,40],['boar',-91,20],['rabbit',-28,39],['deer',31,42],['boar',31,10],['wolf',-82,-13],['wolf',-44,-45],['rabbit',20,-27],['boar',-30,-75]];
 let attackCooldown=0,pending=null;const spear=new T.Group();spear.name='Lance_de_chasse';spear.position.set(0,-.15,.12);visual.box(spear,0,-.4,0,.055,1.2,.055,0x92704e);visual.box(spear,0,-1.04,0,.12,.25,.08,0xb5c9c0);character.getObjectByName('ForearmR').add(spear);spear.visible=false;
 function model(type,x,z,y){const def=SPECIES[type],g=visual.group('Faune_'+type,x,z,y),b=(x,y,z,w,h,d,c)=>visual.box(g,x,y,z,w,h,d,c);b(0,.68,0,.6,.58,1.1,def.color);b(0,1,.6,.42,.46,.5,def.color);b(0,.85,.9,.31,.23,.35,type==='boar'?0x9c8572:def.color);b(0,.88,1.08,.2,.12,.05,0x38473e);for(const side of [-1,1]){b(side*.2,1.08,.8,.045,.07,.09,0x222e2b);b(side*.17,type==='rabbit'?1.58:1.33,.6,.12,type==='rabbit'?.65:.24,.16,def.color)}const legs=[];for(const xx of [-.22,.22])for(const zz of [-.35,.35]){const leg=new T.Group();leg.position.set(xx,.52,zz);g.add(leg);visual.box(leg,0,-.24,0,.16,.48,.18,def.color);visual.box(leg,0,-.49,.03,.18,.1,.23,0x474d40);legs.push(leg)}if(type==='deer')for(const side of [-1,1]){b(side*.24,1.65,.56,.07,.75,.07,0xc5ba93);b(side*.36,1.87,.56,.3,.07,.07,0xc5ba93);b(side*.48,1.97,.56,.06,.22,.07,0xc5ba93)}if(type==='boar')for(const side of [-1,1])b(side*.19,.92,1.04,.07,.25,.07,0xdad5b7);const tail=b(0,.8,-.73,.16,.18,type==='wolf'?.8:.25,def.color);tail.rotation.x=.3;g.scale.setScalar(def.size);return{g,legs}}
 defs.forEach(([type,x,z],i)=>{const spawn=visual.clearSpot(x,z,1);if(!spawn)return;const id='animal-'+i,def=SPECIES[type],s=state.animals[id]??={hp:def.hp,x:spawn.x,z:spawn.z,deadAt:null,looted:false};const y=world.elevation(s.x,s.z);if(!world.canMove(s.x,s.z,y,new Set(),true)){s.x=spawn.x;s.z=spawn.z}const {g,legs}=model(type,s.x,s.z,world.elevation(s.x,s.z));animals.push({id,type,def,s,g,legs,home:spawn,heading:i*2.4,decision:0,alarm:0,hit:0,bite:0,target:new T.Vector3(),moving:0})});
 function reachable(a,range=2.6){return Math.abs(character.position.y-a.g.position.y)<1.5&&Math.hypot(character.position.x-a.s.x,character.position.z-a.s.z)<range&&lineFree(a.s.x,a.s.z,a.g.position.y)}
 function hit(a){if(!active()||a.s.hp<=0||!reachable(a,3))return;const damage=state.spear?10:4;a.s.hp=Math.max(0,a.s.hp-damage);a.alarm=10;a.hit=.25;if(a.s.hp===0){a.s.deadAt=now();a.s.looted=false;reward('hunting',18,1);toast(`${a.def.name} abatido · Recoge el alimento`)}else toast(`${a.def.name} · ${a.s.hp}/${a.def.hp}`);save()}
 function attack(a){if(attackCooldown>0||a.s.hp<=0||!reachable(a)||!spend(3))return;attackCooldown=.8;character.rotation.y=Math.atan2(a.s.x-character.position.x,a.s.z-character.position.z);greyMan.trigger();pending={a,t:.3};a.alarm=10;}
 function interaction(){let found=null;for(const a of animals){if(a.s.looted||!reachable(a))continue;const dist=Math.hypot(a.s.x-character.position.x,a.s.z-character.position.z);if(found&&dist>=found.dist)continue;found={x:a.s.x,z:a.s.z,y:a.g.position.y,dist,label:a.s.hp>0?`Cazar ${a.def.name.toLowerCase()} · ${a.s.hp}/${a.def.hp}`:'Recoger alimento',fn:()=>{if(!reachable(a))return;if(a.s.hp>0)attack(a);else{a.s.looted=true;state.food.raw+=a.def.meat;state.hide+=a.def.hide;toast(`+${a.def.meat} carne cruda${a.def.hide?' · +'+a.def.hide+' piel':''}`);save()}}}}return found}
 function update(dt){spear.visible=state.spear&&attackCooldown>0;if(spear.visible){const tool=character.getObjectByName('Herramienta_recoleccion');if(tool)tool.visible=false}attackCooldown=Math.max(0,attackCooldown-dt);if(pending){pending.t-=dt;if(pending.t<=0){hit(pending.a);pending=null}}if(!active())return;
  for(const a of animals){const {s,g,def}=a;const distance=Math.hypot(character.position.x-s.x,character.position.z-s.z);a.bite=Math.max(0,a.bite-dt);a.hit=Math.max(0,a.hit-dt);a.alarm=Math.max(0,a.alarm-dt);
   if(s.hp<=0){if(s.looted&&now()-s.deadAt>1200&&distance>25){s.hp=def.hp;s.looted=false;s.deadAt=null;s.x=a.home.x;s.z=a.home.z;save()}else{g.visible=!s.looted;g.rotation.z=Math.PI/2;g.position.y=world.elevation(s.x,s.z)+.2;continue}}
   g.visible=true;g.rotation.z=a.hit>0?Math.sin(a.hit*50)*.13:0;
   const sensed=distance<(def.mode==='hostile'?8:def.mode==='territorial'?4.7:6)&&Math.abs(character.position.y-g.position.y)<2&&lineFree(s.x,s.z,g.position.y);
   const homeDistance=Math.hypot(s.x-a.home.x,s.z-a.home.z);const chasing=(def.mode!=='flee')&&(sensed||a.alarm>0)&&distance<16&&homeDistance<20;
   let dx=0,dz=0,speed=0;
   if(def.mode==='flee'&&(sensed||a.alarm>0)){dx=s.x-character.position.x;dz=s.z-character.position.z;speed=def.speed;a.decision=0}
   else if(chasing){dx=character.position.x-s.x;dz=character.position.z-s.z;speed=def.speed;if(distance<1.5){speed=0;if(a.bite<=0&&lineFree(s.x,s.z,g.position.y)){hurt(def.mode==='hostile'?9:7);a.bite=1.8}}}
   else {a.decision-=dt;if(a.decision<=0){a.decision=2.5+Math.random()*4;a.heading+=1+Math.random()*3;a.moving=Math.random()>.3?1:0}if(homeDistance>10){dx=a.home.x-s.x;dz=a.home.z-s.z;speed=1.6}else if(a.moving){dx=Math.sin(a.heading);dz=Math.cos(a.heading);speed=.65}}
   const len=Math.hypot(dx,dz);if(len>.01&&speed){dx=dx/len*speed*dt;dz=dz/len*speed*dt;let moved=false;if(world.canMove(s.x+dx,s.z,g.position.y,unlocked)){s.x+=dx;moved=true}if(world.canMove(s.x,s.z+dz,g.position.y,unlocked)){s.z+=dz;moved=true}if(!moved){a.heading+=1.5;a.decision=1;speed=0}else g.rotation.y=Math.atan2(dx,dz)}
   g.position.set(s.x,world.elevation(s.x,s.z),s.z);for(let i=0;i<a.legs.length;i++)a.legs[i].rotation.x=speed?Math.sin(now()*speed*4+(i===0||i===3?0:Math.PI))*.5:0;
  }
 }
 return {update,interaction,blocks:(x,z)=>animals.some(a=>a.s.hp>0&&Math.abs(character.position.y-a.g.position.y)<1.5&&Math.hypot(x-a.s.x,z-a.s.z)<.45*a.def.size+.35),animals};
}
